// fix_necessity.go は、修正の必要度 (findings[].fix_necessity と fix_necessity_reason)・
// 必要度の下限 (runs[].min_fix_necessity)・判定「下限未満」(verdict: below_minimum)・
// 下限未満の指摘の参照 (findings[].below_minimum_ref) の検査と、生成サマリへの描画を持つ。
// 判定の条件の SSOT は skills/review-triage/references/judgment-flow.md の D9〜D12・E3、
// キーの意味の SSOT は同じディレクトリの record-schema.md。
package main

import (
	"fmt"
	"strings"
)

// recordFixNecessityReason は findings[].fix_necessity_reason を表し、E3 の 2 つの条件の
// 結果を持つ。goal_without_action は条件 1 (困る人は、何もしなくても目的を達成できるか)、
// workaround は条件 2 (困る人が気づいて取れる回避策があるか) の結果で、条件 1 が not-holds の
// ときだけ書く。必要度 (fix_necessity) はこの結果から決まる (fixNecessityFromReason)。
// 判定理由の文に書く形にしないのは、書き忘れを検査で見つけられないため (prior_defect と同じ)。
type recordFixNecessityReason struct {
	GoalWithoutAction string `yaml:"goal_without_action"`
	Workaround        string `yaml:"workaround"`
	WorkaroundReason  string `yaml:"workaround_reason"`
}

// recordBelowMinimumRef は findings[].below_minimum_ref を表す。D9 の (1) (前の回までの
// 下限未満の指摘と問題が同じ) が成り立った指摘に書く。run と finding は参照先 (1 始まりの
// 回番号と、その回の指摘の id)、line_check は D9 の (2) (対象の行が変わっていない) の結果。
type recordBelowMinimumRef struct {
	Run        int    `yaml:"run"`
	Finding    int    `yaml:"finding"`
	LineCheck  string `yaml:"line_check"`
	LineReason string `yaml:"line_reason"`
}

// fixNecessityRank は必要度の高さを返す (must が最も高い)。列挙に無い値は 0。
func fixNecessityRank(v string) int {
	switch v {
	case "must":
		return 3
	case "should":
		return 2
	case "could":
		return 1
	}
	return 0
}

// fixNecessityJa は必要度を生成サマリに出す表記にする。
func fixNecessityJa(v string) string {
	switch v {
	case "must":
		return "Must"
	case "should":
		return "Should"
	case "could":
		return "Could"
	}
	return recordCell(v)
}

// fixNecessityBelow は、必要度が下限に満たないかを返す。下限が無ければ満たないことは無い。
// どちらかが列挙に無い値のときは、比べられないので偽を返す (列挙の誤りは別に報告する)。
func fixNecessityBelow(necessity, minimum string) bool {
	n, m := fixNecessityRank(necessity), fixNecessityRank(minimum)
	return n > 0 && m > 0 && n < m
}

// fixNecessityFromReason は、2 つの条件の結果から決まる必要度を返す。どちらかの条件が undecided なら
// 空を返す。結果の形 (書く組み合わせ) は呼び出し元が先に検査する。
func fixNecessityFromReason(r *recordFixNecessityReason) string {
	switch r.GoalWithoutAction {
	case "holds":
		return "could"
	case "not-holds":
		switch r.Workaround {
		case "holds":
			return "should"
		case "not-holds":
			return "must"
		}
	}
	return ""
}

// judgmentOmitted は、D9 で当たって判定を省略した指摘 (A3・B2) かを返す。
func judgmentOmitted(fd recordFinding) bool {
	return fd.BelowMinimumRef != nil && fd.BelowMinimumRef.LineCheck == "holds"
}

// recordFixNecessityFirstRun は、記録の中で最初に fix_necessity_reason か、回の
// min_fix_necessity を書いた回の添字を返す。無ければ -1。この回と、それより後の回では
// fix_necessity_reason を必須にする。過去の記録を書き換えさせずに通すための決め方で、理由は
// recordPriorDefectFirstRun と同じ。回の下限も見るのは、下限を書いた回は必要度を判定する規則で
// 判定した回なので、その回で必要度を全件書き忘れた記録を報告するため。
func recordFixNecessityFirstRun(runs []recordRun) int {
	for ri, run := range runs {
		if run.MinFixNecessity != "" {
			return ri
		}
		for _, fd := range run.Findings {
			if fd.FixNecessityReason != nil {
				return ri
			}
		}
	}
	return -1
}

// recordFixNecessityProblems は、判定を省略していない指摘 1 件の必要度を検査する。
// 書く条件は E3 を行ったかで決まる。判定フローでは、D4 で根拠を確認した指摘
// (premise_check.result が verified) だけが E3 に進む。required が偽の回
// (recordFixNecessityFirstRun の回より前の回) では、無くても報告しない。
// minimum はその回の必要度の下限 (無ければ空)。
func recordFixNecessityProblems(required bool, minimum string, fd recordFinding) []string {
	var problems []string
	add := func(format string, args ...any) {
		problems = append(problems, fmt.Sprintf(format, args...))
	}
	if fd.FixNecessity != "" && fixNecessityRank(fd.FixNecessity) == 0 {
		add("fix_necessity は must / should / could のいずれか (決められなければ書かない): %q", fd.FixNecessity)
	}
	// 下限未満にできるのは、必要度を決めた指摘だけ。必要度の無い下限未満は、下の対応の
	// 検査では見つからない (理由の無い指摘と、決められなかった指摘の両方がある) ので、ここで見る。
	if fd.Verdict == "below_minimum" && fd.FixNecessity == "" {
		add("verdict が below_minimum なのに fix_necessity がありません (下限未満にできるのは、必要度を決めた指摘だけ)")
	}
	verified := fd.PremiseCheck.Result == "verified"
	r := fd.FixNecessityReason
	if r == nil {
		switch {
		case fd.FixNecessity != "":
			add("fix_necessity があるのに fix_necessity_reason がありません (必要度は、E3 の 2 つの条件の結果から決める)")
		case verified && required:
			add("fix_necessity_reason がありません (D4 で根拠を確認した指摘は E3 で必要度を判定するので、条件の結果を書く。この記録では、この回かそれより前の回で fix_necessity_reason を書いている)")
		}
		return problems
	}
	if !verified {
		// E3 に進んでいない指摘の必要度は、どの値でも判定の経路と矛盾するので、中身は検査しない。
		add("fix_necessity_reason は E3 を行った指摘 (premise_check.result が verified) にだけ書く (result %q)", fd.PremiseCheck.Result)
		return problems
	}
	shapeValid := true
	switch r.GoalWithoutAction {
	case "holds", "not-holds", "undecided":
	default:
		shapeValid = false
		add("fix_necessity_reason.goal_without_action は holds / not-holds / undecided のいずれか: %q", r.GoalWithoutAction)
	}
	switch {
	case r.GoalWithoutAction == "not-holds":
		switch r.Workaround {
		case "holds", "not-holds", "undecided":
		case "":
			shapeValid = false
			add("fix_necessity_reason.workaround がありません (goal_without_action が not-holds なら条件 2 を判定する)")
		default:
			shapeValid = false
			add("fix_necessity_reason.workaround は holds / not-holds / undecided のいずれか: %q", r.Workaround)
		}
		if r.Workaround != "" && r.WorkaroundReason == "" {
			add("fix_necessity_reason.workaround_reason がありません (回避策の手段か、無い理由か、決められなかった理由)")
		}
	case shapeValid:
		// 条件 1 が成り立つか決められなければ、条件 2 は判定しない。
		if r.Workaround != "" || r.WorkaroundReason != "" {
			shapeValid = false
			add("fix_necessity_reason.workaround と workaround_reason は、goal_without_action が not-holds のときだけ書く (goal_without_action %q)", r.GoalWithoutAction)
		}
	}
	if !shapeValid {
		return problems
	}
	want := fixNecessityFromReason(r)
	if fd.FixNecessity != want {
		if want == "" {
			add("fix_necessity_reason では必要度が決まらない (undecided がある) のに、fix_necessity %q があります", fd.FixNecessity)
		} else {
			add("fix_necessity は、fix_necessity_reason から決まる %s と違います: %q", want, fd.FixNecessity)
		}
		return problems
	}
	switch {
	case want == "" && fd.Verdict == "adopted":
		add("必要度を決められなかった (fix_necessity_reason に undecided がある) のに、verdict が adopted です (決められなければ H8 の保留)")
	case fd.Verdict == "adopted" && fixNecessityBelow(want, minimum):
		add("必要度 %s が回の下限 %s に満たないのに、verdict が adopted です (下限に満たなければ B1 の下限未満)", want, minimum)
	case fd.Verdict == "below_minimum" && want != "" && !fixNecessityBelow(want, minimum):
		if minimum == "" {
			add("回に下限 (min_fix_necessity) が無いのに、verdict が below_minimum です")
		} else {
			add("必要度 %s が回の下限 %s 以上なのに、verdict が below_minimum です", want, minimum)
		}
	}
	return problems
}

// belowMinimumRefTarget は below_minimum_ref の参照先の指摘を返す。参照先にできるのは、
// この回 (添字 ri) より前の回の、必要度を判定して下限未満にした指摘 (B1) だけ。
// 判定を省略した指摘 (B2) は必要度を持たないので、参照先にしない。
func belowMinimumRefTarget(doc *recordDoc, ri int, ref *recordBelowMinimumRef) (*recordFinding, string) {

type lineResult struct {
	line int
	kind string
	note string
}

// check は、opts の行が全量の起点からレビューした内容まで変わっていないかを確認する。
// 入力の誤り (解決できない版・レビューした内容に無いファイルや行) は error で返し、結果にしない。
func check(opts options) (result, error) {
	if err := checkGitVersion(opts.worktree); err != nil {
		return result{}, err
	}
	top, err := toplevel(opts.root)
	if err != nil {
		return result{}, err
	}
	g := gitRunner{root: top}

	base, found, err := g.commit(opts.base)
	if err != nil {
		return result{}, err
	} else if !found {
		return result{}, inputf("-base をコミットに解決できません: %s", opts.base)
	}
	targetName := opts.rev
	if opts.worktree {
		targetName = "HEAD"
	}
	target, found, err := g.commit(targetName)
	if err != nil {
		return result{}, err
	} else if !found {
		return result{}, inputf("レビューした内容のコミット (%s) を解決できません", targetName)
	}

	// 全量の起点がレビューした内容のコミットと同じなら、範囲 <起点>..<コミット> には起点でないコミットが無く、
	// git blame ではブランチの変更と前からある行を区別できない (git blame の振る舞いは下の sameCommitResult
	// を呼ぶ箇所のコメント)。
	// フラグ -allow-same-commit (判定ノード D9) では、起点は前の指摘を判定した回のコミットで、
	// 確認するのは、そのコミットからレビューした内容までに行が変わっていないかである。ブランチの変更と
	// 区別する必要が無いので、同じコミットでも確認できないとしない。
	if base == target && !opts.allowSameCommit {
		return result{kind: unverifiable, reason: fmt.Sprintf("起点 %s が、レビューした内容のコミット (%s) と同じで、このブランチの変更と前からある行を区別できない", short(base), targetName)}, nil
	}
	ok, err := g.isAncestor(base, target)
	if err != nil {
		return result{}, asRun(err)
	}
	if !ok {
		return result{kind: unverifiable, reason: fmt.Sprintf("起点 %s が、レビューした内容のコミット (%s) の祖先ではない", short(base), targetName)}, nil
	}

	// 指摘の file は、レビューした内容にあるはず (根拠の照合 E1 を通っている)。無ければ入力の誤り。
	targetEntry, err := g.entry(target, opts.file)
	if err != nil {
		return result{}, err
	}
	if opts.worktree {
		st, err := os.Stat(filepath.Join(top, filepath.FromSlash(opts.file)))
		if err != nil || !st.Mode().IsRegular() {
			return result{}, inputf("作業ツリーに -file のファイルがありません: %s", opts.file)
		}
	} else if targetEntry != entryFile && targetEntry != entrySymlink {
		return result{}, inputf("レビューした内容 (%s) に -file のファイルがありません: %s", opts.rev, opts.file)
	}

	if baseEntry, err := g.entry(base, opts.file); err != nil {
		return result{}, err
	} else if baseEntry != entryFile && baseEntry != entrySymlink {
		return result{kind: notHolds, reason: fmt.Sprintf("起点 %s に同じパスのファイルが無い (このブランチで作った・改名した・移したファイル)", short(base))}, nil
	}
	if opts.worktree && targetEntry != entryFile && targetEntry != entrySymlink {
		return result{kind: notHolds, reason: "HEAD に同じパスのファイルが無い (コミットしていないファイル)"}, nil
	}

	// 次の 3 つは、レビュアが読む内容とコマンド git blame が見る内容が違いうる。シンボリックリンクと clean
	// フィルタは行番号が対応せず、属性 ident は行の中の書き換えを、比べる前の変換で戻す。どれも書き換えた行が
	// 起点のままと報告されうる (誤った holds) ので、方式によらず確認しない。
	// git はシンボリックリンクのリンクの文字列を 1 行のブロブとして記録し、git blame もそれを見るが、
	// レビュアはリンクの先の内容を読む
	if targetEntry == entrySymlink {
		return result{kind: unverifiable, reason: "指摘のファイルが追跡中のシンボリックリンクで、レビュアが読むリンクの先の内容と、git が記録するリンクの文字列の行番号が対応しない"}, nil
	}
	// clean フィルタは、作業ツリーの内容 (レビュアが読む、フィルタの前の内容) を変換してから記録し、
	// git blame もフィルタの後の内容 (コミットの内容と、オプション --contents で渡した内容) を見る。フィルタが
	// 行を増やしたり消したりすると、行番号がずれる。属性 ident は、記録するときに「$Id: … $」を「$Id$」へ戻し、
	// コマンド git hash-object --path と git blame --contents も同じ変換を当ててから比べるので、「$Id: … $」の
	// 中の書き換えが見えない。-rev では、コミットしていない変更の確認より前に、属性 filter と ident を調べる (その確認が実行する
	// git hash-object --path が、フィルタのプログラムを実行しないように)
	attr, err := g.convertingAttribute(opts.file)
	if err != nil {
		return result{}, err
	}
	switch attr {
	case "filter":
		return result{kind: unverifiable, reason: "指摘のファイルに clean フィルタ (属性 filter) が設定されていて、作業ツリーの内容 (フィルタの前) と、git blame が見るフィルタの後の内容の行番号がずれうる"}, nil
	case "ident":
		return result{kind: unverifiable, reason: "指摘のファイルに属性 ident が設定されていて、git は「$Id: … $」の中を「$Id$」へ戻してから内容を比べるので、レビュアが読んだその中の書き換えを確認できない"}, nil
	}

	if !opts.worktree {
		// 結果のファイルで受け取ったレビューは、共有の作業ツリーでコミットしていない変更を見た可能性があり、
		// 結果のファイルからは分からない。ほかのファイルの変更は、指摘の file の行番号を変えないので見ない。
		// 比べる相手は HEAD ではなく、レビューした内容のコミットにする。-rev が HEAD より前なら、レビューの
		// 時点ではコミットしていなかった編集が、その後のコミットに入っていることがあり、HEAD と比べても見つからない
		changed, err := g.hasUncommittedChange(top, target, targetEntry, opts.file)
		if err != nil {
			return result{}, asRun(err)
		}
		if changed {
			return result{kind: unverifiable, reason: fmt.Sprintf("指摘のファイルの作業ツリーかインデックスの内容が、レビューした内容のコミット (%s) と違う (コミットしていない変更があるか、そのコミットより後のコミットで変わった) ので、レビューがどの内容を見たかが分からない", targetName)}, nil
		}
	}

	if base == target && !opts.worktree {
		// ここに来るのは、フラグ -allow-same-commit を付けて、-rev に起点と同じコミットを渡したときだけ。
		// 範囲 <起点>..<起点> には起点でないコミットが無く、git blame はこの範囲を渡されると、HEAD を親として
		// 作業ツリーの内容を調べる。-rev が HEAD と違うと、結果が判定の時点の HEAD で変わる。レビューした内容は
		// 起点のコミットそのもので、指摘のファイルにコミットしていない変更が無いことも上で確認したので、
		// git blame を実行せずに、どの行も起点にあったままとする。-worktree のときは、レビューした内容の
		// コミットが HEAD なので、下の git blame が HEAD を親として作業ツリーの内容を調べるのが正しい。
		return sameCommitResult(g, base, target, opts)
	}

	blamed, err := g.blame(base, target, opts)
	if err != nil {
		return result{}, err
	}
	return classify(base, opts.file, blamed), nil
}

